mapper.update:
UPDATE devine_moments 
SET likeCount = likeCount + #{increment} 
WHERE momentId = #{momentId}

UPDATE devine_moments 
SET commentCount = commentCount + #{increment} 
WHERE momentId = #{momentId}

mapper.select:
SELECT COUNT(*) > 0 
FROM devine_moments 
WHERE momentId = #{momentId}

SELECT COUNT(*) > 0 
FROM devine_moments 
WHERE momentId = #{momentId} AND userId = #{userId}
